from pathlib import Path
import json
P=Path(__file__).resolve().parent

def main():
 a=json.loads((P/'assessment.json').read_text());r=json.loads((P/'result.json').read_text());lines=['# Four-arm retained research screen — 29 October 2026','', '**Screen completed. No automatic promotion.** All four endpoints are retained as research artifacts; neither a natural-conversation acceptance test nor a final test was run.','', '## Endpoint comparison','', '| Arm | Wording | Replay | D correct | D rate | State conversations | Native NLL | NLL change | Acquisition gates |','|---|---|---:|---:|---:|---:|---:|---:|---|']
 for x in a['arms']:
  lines.append(f"|{x['arm']}|{x['wording']}|{x['replay_coefficient']}|{x['D']['correct']}/{x['D']['total']}|{100*x['D_accuracy']:.1f}%|{x['D_state']['complete']}/{x['D_state']['total']}|{x['native_nll']:.4f}|{x['native_nll_percent_change']:+.1f}%|{'PASS' if x['acquisition_qualified'] else 'FAIL'}|")
 lines+=['','D means unseen fact combinations and reserved instruction wording, relative to the prepared curriculum. These are synthetic prerequisite cases, not general conversation. Native NLL is compared with the shared source baseline '+f"{a['source_native_nll']:.6f}." ,'','## Matched wording contrasts','']
 for x in a['paired_diversity_comparisons']:
  lo,hi=x['stratified_cluster_bootstrap_95_interval'];lines.append(f"- Replay {x['replay']}: diverse versus canonical, {x['D_turn_gains']} gains and {x['D_turn_losses']} losses across {x['D_turns']} D turns; difference {100*x['D_accuracy_difference']:+.1f} percentage points. Descriptive cluster-bootstrap interval [{100*lo:+.1f}, {100*hi:+.1f}] points.")
 lines+=['','The interval resamples scenario clusters within tasks. It does not estimate variation across training seeds or independent linguistic families. This is one seed and four reserved wording strings per task. No causal generalization beyond this controlled packet is justified.','','## Task failures','', '|Task|Canonical + replay|Diverse + replay|Canonical, no replay|Diverse, no replay|','|---|---:|---:|---:|---:|']
 for task in sorted(a['arms'][0]['D_task_accuracy']):lines.append('|'+task+'|'+ '|'.join(f"{100*x['D_task_accuracy'][task]:.1f}%" for x in a['arms'])+'|')
 lines+=['','Thresholds were fixed before launch: D overall >=90%, each task >=80%, whole state conversations >=80%, and both-correct counterfactual groups >=80%. These are operational prerequisite gates, not external standards. No borderline or unrecognized output was silently upgraded. Raw unmatched clarification outputs remain flagged for review.','','## Accounting','',f"Cumulative totals, including all prior calibration: {r['charges']['updates']:,} optimizer applications; {r['charges']['positions']:,} input positions; {r['charges']['assistant']:,} assistant/EOS targets; {r['charges']['narrative']:,} narrative targets; {r['seconds']/60:.2f} active-model minutes. The screen itself added exactly4,000 updates; calibration contributed612. Limits were4,612 updates,50M positions,1M assistant targets,10M narrative targets and150 total active minutes.",'','The successor ledger imported the calibration charge once and preserved its source ledger unchanged. All four arms started from identical original foundation parameters, fresh optimizer and the same seed. No checkpoint from the disposable calibration was used as a retained source. Checkpoint I/O was timed; scheduled evaluations used generated history and normal EOS. Checkpoints were saved every25 updates; this changes only durability frequency, not training arithmetic or data.','','## Decision boundaries','',f"Acquisition-qualified arms: {a['acquisition_qualified_arms'] or 'none'}. The original source behavior baseline remains0/80, so behavioral preservation is INCONCLUSIVE rather than passed. Native narrative retention is a limited distribution-specific proxy. The historical+5% line did not stop branches or promote them.",'',f"The predeclared same-replay pair rule suggests arms {a['suggested_confirmation_pair']} for potential confirmation. This is an analytical selection, not approval to run more seeds or a claim that either model is acceptable. All arms and their failures remain reported. Read the final reassessment alongside these results before further training.",'','[Machine-readable assessment](assessment.json) · [Execution result](result.json) · [Calibration carry-forward](carry-forward.json)']
 (P/'REPORT.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
